from safety_evals.loader import parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_monitor_summary_basic():
    e = [{"id": "a", "day": 1, "flagged": True}, {"id": "b", "day": 2, "flagged": False}]
    assert monitor_summary({"g": e}, 1)["groups"] == 1


def test_monitor_flag_rate_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": None}] * 3, "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"c": []}) == 0.0


def test_window_lengths():
    assert flags_in_window([3, 0, 2], 0) == 0
    assert flags_in_window([3, 0, 2], 2) == 2
    assert flags_in_window([3, 0, 2], 4) == 5


def test_group_rates_and_ranking():
    groups = {"z": [{"flagged": False}], "c": [], "b": [{"flagged": True}], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", None), ("z", 0.0)]
    assert top_flagged_groups(groups, 4) == ["a", "b", "z"]
    assert top_flagged_groups(groups, 1) == ["a"]


def test_streak_resets_at_nonpositive_counts():
    assert longest_flag_streak([1, 0, 1, 2, -1, 3]) == 2
    assert longest_flag_streak([]) == 0


def test_summary_uses_calendar_days_and_nonempty_groups():
    events = parse_transcript_log(["a,1,1", "b,7,0", "c,8,"])
    assert monitor_summary({"g": events, "empty": []}, 4) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert monitor_summary({}, 4) == {"rate": 0.0, "recent": 0, "groups": 0}

