import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log


def test_parse_skips_comments_and_strips_fields():
    lines = ["", " \t", "  # comment", " a , 3 , 0 ", "b, 4,  "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": False},
        {"id": "b", "day": 4, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["a,1", "a,1,1,extra", "a,today,0"])
def test_parse_errors_count_skipped_lines(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "", "x,0,1", bad])


def test_dedupe_keeps_last_record_and_sorts():
    events = parse_transcript_log(["z,5,1", "c,1,0", "b,1,0", "z,0,0"])
    assert dedupe_transcripts(events) == [events[3], events[2], events[1]]


def test_daily_counts_cover_only_inclusive_range():
    events = parse_transcript_log(["a,1,1", "b,2,1", "c,2,1", "d,3,", "e,4,1", "f,5,1"])
    assert daily_flag_counts(events, 2, 4) == [2, 0, 1]
    assert daily_flag_counts(events, 4, 2) == []

